import { Injectable, inject, signal, computed } from '@angular/core';
import { Observable, of } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';
import { CclServiceWrapperService } from './ccl-service-wrapper.service';
import {
  MhaPdsConfiguration,
  SaveResult,
  isMhaPdsConfiguration
} from '../models/mha-pds-configuration.model';

/**
 * Configuration loading state
 */
export interface ConfigurationState {
  loading: boolean;
  loaded: boolean;
  error: string | null;
  lastUpdated: Date | null;
}

/**
 * Angular service for managing MHA PDS configuration
 *
 * Provides methods to load and save configuration from/to the CCL backend
 * via gbin_mha_pds_service. Supports both online (live CCL) and offline
 * (mock) modes transparently through CclServiceWrapperService.
 *
 * Usage:
 *   const configService = inject(MhaPdsConfigurationService);
 *
 *   // Load configuration
 *   configService.getConfiguration().subscribe(config => {
 *     console.log('Configuration loaded:', config);
 *   });
 *
 *   // Get cached configuration (loads if not cached)
 *   configService.getConfigurationCached().subscribe(config => {
 *     // Uses cache if available
 *   });
 *
 *   // Save configuration
 *   configService.saveConfiguration(updatedConfig).subscribe(result => {
 *     if (result.saved) {
 *       console.log('Configuration saved successfully');
 *     }
 *   });
 */
@Injectable({
  providedIn: 'root'
})
export class MhaPdsConfigurationService {
  private cclWrapper = inject(CclServiceWrapperService);

  // Cached configuration using signals for reactive state
  private configCache = signal<MhaPdsConfiguration | null>(null);

  // Loading state
  private loadingState = signal<ConfigurationState>({
    loading: false,
    loaded: false,
    error: null,
    lastUpdated: null
  });

  /**
   * Read-only computed signal for configuration
   */
  readonly configuration = computed(() => this.configCache());

  /**
   * Read-only computed signal for loading state
   */
  readonly state = computed(() => this.loadingState());

  /**
   * Check if configuration is currently cached
   */
  readonly isCached = computed(() => this.configCache() !== null);

  /**
   * Check if currently loading
   */
  readonly isLoading = computed(() => this.loadingState().loading);

  /**
   * Load configuration from CCL backend
   *
   * Always fetches fresh configuration from the backend, bypassing cache.
   * Updates the cache with the result.
   *
   * @returns Observable<MhaPdsConfiguration> - The loaded configuration
   */
  getConfiguration(): Observable<MhaPdsConfiguration> {
    return new Observable<MhaPdsConfiguration>(subscriber => {
      this.loadingState.update(state => ({
        ...state,
        loading: true,
        error: null
      }));

      const requestId = `getMHAPDSConfiguration-${Date.now()}`;

      try {
        this.cclWrapper.load(
          {
            customScript: {
              script: [
                {
                  name: 'gbin_mha_pds_service:group1',
                  run: 'pre',
                  id: requestId,
                  reference: true,
                  parameters: {
                    requestType: 'getMHAPDSConfiguration',
                    requestId: Date.now(),
                    requestData: ''
                  }
                }
              ],
              clearPatientSource: true
            }
          },
          [{ personId: 0, encntrId: 0 }],
          () => {
            const response = this.cclWrapper.get(requestId);

            if (response) {
              if (response.error) {
                const error = `CCL Error: ${response.error}`;
                this.loadingState.update(state => ({
                  ...state,
                  loading: false,
                  error
                }));
                subscriber.error(new Error(error));
              } else if (isMhaPdsConfiguration(response)) {
                // Valid configuration response
                this.configCache.set(response);
                this.loadingState.update(state => ({
                  ...state,
                  loading: false,
                  loaded: true,
                  error: null,
                  lastUpdated: new Date()
                }));
                subscriber.next(response);
                subscriber.complete();
              } else {
                // Response doesn't match expected structure
                const error = 'Invalid configuration structure received from CCL';
                console.error('[MhaPdsConfigurationService] Invalid response structure:', response);
                this.loadingState.update(state => ({
                  ...state,
                  loading: false,
                  error
                }));
                subscriber.error(new Error(error));
              }
            } else {
              const error = 'No response from CCL script';
              this.loadingState.update(state => ({
                ...state,
                loading: false,
                error
              }));
              subscriber.error(new Error(error));
            }
          }
        );
      } catch (err) {
        const error = err instanceof Error ? err.message : 'Unknown error loading configuration';
        this.loadingState.update(state => ({
          ...state,
          loading: false,
          error
        }));
        subscriber.error(new Error(error));
      }
    });
  }

  /**
   * Get configuration from cache if available, otherwise load from backend
   *
   * Uses cached configuration if available, otherwise fetches from CCL.
   * This is the preferred method for most use cases.
   *
   * @returns Observable<MhaPdsConfiguration> - The configuration (cached or fresh)
   */
  getConfigurationCached(): Observable<MhaPdsConfiguration> {
    const cached = this.configCache();
    if (cached) {
      return of(cached);
    }
    return this.getConfiguration();
  }

  /**
   * Save configuration to CCL backend
   *
   * Sends the updated configuration to the backend for persistence.
   * On success, updates the local cache with the saved configuration.
   *
   * @param config - The configuration to save
   * @returns Observable<SaveResult> - The result of the save operation
   */
  saveConfiguration(config: MhaPdsConfiguration): Observable<SaveResult> {
    return new Observable<SaveResult>(subscriber => {
      const requestId = `saveMHAPDSConfiguration-${Date.now()}`;

      // Serialize configuration to JSON for CCL
      let configJson: string;
      try {
        configJson = JSON.stringify(config);
      } catch (err) {
        const error: SaveResult = {
          saved: false,
          timestamp: new Date().toISOString(),
          status: 'F',
          errors: ['Failed to serialize configuration to JSON']
        };
        subscriber.next(error);
        subscriber.complete();
        return;
      }

      try {
        this.cclWrapper.load(
          {
            customScript: {
              script: [
                {
                  name: 'gbin_mha_pds_service:group1',
                  run: 'pre',
                  id: requestId,
                  reference: true,
                  parameters: {
                    requestType: 'saveMHAPDSConfiguration',
                    requestId: Date.now(),
                    requestData: configJson
                  }
                }
              ],
              clearPatientSource: true
            }
          },
          [{ personId: 0, encntrId: 0 }],
          () => {
            const response = this.cclWrapper.get(requestId);

            if (response) {
              if (response.error) {
                const result: SaveResult = {
                  saved: false,
                  timestamp: new Date().toISOString(),
                  status: 'F',
                  errors: [response.error]
                };
                subscriber.next(result);
                subscriber.complete();
              } else if (response.saved !== undefined) {
                // Direct save response
                const result: SaveResult = {
                  saved: response.saved === true,
                  timestamp: response.timestamp || new Date().toISOString(),
                  status: response.saved ? 'S' : 'F',
                  errors: response.errors || []
                };

                // Update cache on success
                if (result.saved) {
                  this.configCache.set(config);
                  this.loadingState.update(state => ({
                    ...state,
                    lastUpdated: new Date()
                  }));
                }

                subscriber.next(result);
                subscriber.complete();
              } else if (response.status_data?.status === 'S') {
                // CCL-style status response
                const result: SaveResult = {
                  saved: true,
                  timestamp: new Date().toISOString(),
                  status: 'S'
                };

                // Update cache on success
                this.configCache.set(config);
                this.loadingState.update(state => ({
                  ...state,
                  lastUpdated: new Date()
                }));

                subscriber.next(result);
                subscriber.complete();
              } else {
                // Unknown response format, treat as failure
                const result: SaveResult = {
                  saved: false,
                  timestamp: new Date().toISOString(),
                  status: 'F',
                  errors: ['Unexpected response format from CCL']
                };
                subscriber.next(result);
                subscriber.complete();
              }
            } else {
              const result: SaveResult = {
                saved: false,
                timestamp: new Date().toISOString(),
                status: 'F',
                errors: ['No response from CCL script']
              };
              subscriber.next(result);
              subscriber.complete();
            }
          }
        );
      } catch (err) {
        const result: SaveResult = {
          saved: false,
          timestamp: new Date().toISOString(),
          status: 'F',
          errors: [err instanceof Error ? err.message : 'Unknown error saving configuration']
        };
        subscriber.next(result);
        subscriber.complete();
      }
    });
  }

  /**
   * Clear the cached configuration
   *
   * Forces the next getConfigurationCached() call to fetch fresh data.
   */
  clearCache(): void {
    this.configCache.set(null);
    this.loadingState.update(state => ({
      ...state,
      loaded: false,
      lastUpdated: null
    }));
  }

  /**
   * Refresh configuration from backend
   *
   * Convenience method that clears cache and loads fresh configuration.
   *
   * @returns Observable<MhaPdsConfiguration> - The refreshed configuration
   */
  refreshConfiguration(): Observable<MhaPdsConfiguration> {
    this.clearCache();
    return this.getConfiguration();
  }
}
