import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Input,
  Output
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { SubmissionConfig } from '../../models/mha-pds-configuration.model';

/**
 * Configuration section for submission settings
 *
 * Allows editing of:
 * - Batch size
 * - Schedule frequency
 * - Max retries
 * - Retry delay
 */
@Component({
  selector: 'app-config-section-submission',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="section-content">
      <div class="form-grid">
        <!-- Batch Size -->
        <div class="form-group">
          <label for="batchSize">Batch Size</label>
          <input
            type="number"
            id="batchSize"
            class="form-control"
            [ngModel]="config.BATCH_SIZE"
            (ngModelChange)="onFieldChange('BATCH_SIZE', $event)"
            min="1"
            max="1000"
            step="10" />
          <small class="help-text">Number of records to process per batch (1-1000)</small>
        </div>

        <!-- Schedule Frequency -->
        <div class="form-group">
          <label for="scheduleFrequency">Schedule Frequency</label>
          <select
            id="scheduleFrequency"
            class="form-control"
            [ngModel]="config.SCHEDULE_FREQUENCY"
            (ngModelChange)="onFieldChange('SCHEDULE_FREQUENCY', $event)">
            <option value="HOURLY">Hourly</option>
            <option value="DAILY">Daily</option>
            <option value="WEEKLY">Weekly</option>
            <option value="MANUAL">Manual Only</option>
          </select>
          <small class="help-text">How often to run automatic submissions</small>
        </div>

        <!-- Max Retries -->
        <div class="form-group">
          <label for="maxRetries">Max Retries</label>
          <input
            type="number"
            id="maxRetries"
            class="form-control"
            [ngModel]="config.MAX_RETRIES"
            (ngModelChange)="onFieldChange('MAX_RETRIES', $event)"
            min="0"
            max="10"
            step="1" />
          <small class="help-text">Maximum retry attempts for failed submissions (0-10)</small>
        </div>

        <!-- Retry Delay -->
        <div class="form-group">
          <label for="retryDelay">Retry Delay (minutes)</label>
          <input
            type="number"
            id="retryDelay"
            class="form-control"
            [ngModel]="config.RETRY_DELAY_MINUTES"
            (ngModelChange)="onFieldChange('RETRY_DELAY_MINUTES', $event)"
            min="1"
            max="120"
            step="5" />
          <small class="help-text">Wait time between retry attempts (1-120 minutes)</small>
        </div>
      </div>

      <!-- Schedule Summary -->
      <div class="schedule-summary">
        <h4>Schedule Summary</h4>
        <p>
          @switch (config.SCHEDULE_FREQUENCY) {
            @case ('HOURLY') {
              Submissions will be processed every hour in batches of {{ config.BATCH_SIZE }} records.
            }
            @case ('DAILY') {
              Submissions will be processed daily in batches of {{ config.BATCH_SIZE }} records.
            }
            @case ('WEEKLY') {
              Submissions will be processed weekly in batches of {{ config.BATCH_SIZE }} records.
            }
            @case ('MANUAL') {
              Automatic submissions are disabled. Records will only be submitted manually.
            }
            @default {
              Submissions will be processed in batches of {{ config.BATCH_SIZE }} records.
            }
          }
          @if (config.MAX_RETRIES > 0) {
            Failed submissions will be retried up to {{ config.MAX_RETRIES }} times with a {{ config.RETRY_DELAY_MINUTES }}-minute delay between attempts.
          } @else {
            Failed submissions will not be automatically retried.
          }
        </p>
      </div>
    </div>
  `,
  styles: [`
    .section-content {
      max-width: 800px;
    }

    .form-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 20px;

      @media (max-width: 600px) {
        grid-template-columns: 1fr;
      }
    }

    .form-group {
      display: flex;
      flex-direction: column;
      gap: 6px;

      label {
        font-weight: 500;
        color: #333;
        font-size: 14px;
      }

      .form-control {
        padding: 10px 12px;
        border: 1px solid #ced4da;
        border-radius: 4px;
        font-size: 14px;
        transition: border-color 0.2s, box-shadow 0.2s;

        &:focus {
          outline: none;
          border-color: #0078d4;
          box-shadow: 0 0 0 3px rgba(0, 120, 212, 0.1);
        }
      }

      select.form-control {
        cursor: pointer;
        background-color: white;
      }

      .help-text {
        color: #6c757d;
        font-size: 12px;
      }
    }

    .schedule-summary {
      margin-top: 24px;
      padding: 16px;
      background-color: #f8f9fa;
      border: 1px solid #e9ecef;
      border-radius: 6px;

      h4 {
        margin: 0 0 8px 0;
        color: #333;
        font-size: 14px;
        font-weight: 600;
      }

      p {
        margin: 0;
        color: #555;
        font-size: 13px;
        line-height: 1.6;
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfigSectionSubmission {
  @Input() config!: SubmissionConfig;
  @Output() configChange = new EventEmitter<SubmissionConfig>();

  onFieldChange(field: keyof SubmissionConfig, value: any): void {
    const updatedConfig = { ...this.config, [field]: value };
    this.configChange.emit(updatedConfig);
  }
}
