/**
 * MHA PDS Configuration Model
 * Represents the complete configuration structure returned from gbin_mha_pds_service
 *
 * This model matches the JSON structure stored in dm_info/long_blob and
 * returned by the getMHAPDSConfiguration request type.
 */

/**
 * Code table definition for MHA PDS value sets
 */
export interface CodeTable {
  CODE_TABLE_ID: string;
  CODE_TABLE_NAME: string;
}

/**
 * Code table mapping entry for value translation
 */
export interface CodeTableMapping {
  CODE_TABLE_ID: string;
  CODE: string;
  LABEL: string;
  DESCRIPTION: string;
  CODE_VALUE_SOURCE: string;
  CODE_SYSTEM: string;
  VALUE_SET_URL: string;
  COMMENT: string;
}

/**
 * Submit field configuration for FHIR payload building
 */
export interface SubmitField {
  FIELD_CODE: string;
  DESCRIPTION: string;
  ACTIVE_IND: number;
}

/**
 * FHIR resource code configuration
 */
export interface FhirResourceCode {
  RESOURCE_TYPE: string;
  FIELD_NAME: string;
  CODE: string;
  LABEL: string;
  CODE_VALUE_SOURCE: string;
  CODE_SYSTEM: string;
  VALUE_SET_URL: string;
  IS_DEFAULT: number;
}

/**
 * Mirth Connect server configuration
 */
export interface MirthConnectConfig {
  URL: string;
  USERNAME: string;
  PASSWORD: string;
  TIMEOUT_SECONDS: number;
  RETRY_ATTEMPTS: number;
}

/**
 * Submission configuration settings
 */
export interface SubmissionConfig {
  BATCH_SIZE: number;
  SCHEDULE_FREQUENCY: string;
  MAX_RETRIES: number;
  RETRY_DELAY_MINUTES: number;
}

/**
 * Processing configuration flags
 */
export interface ProcessingConfig {
  ENABLE_DUMMY_MODE: number;
  ENABLE_DETAILED_LOGGING: number;
  ENABLE_ERROR_NOTIFICATIONS: number;
}

/**
 * MHA PDS field mapping configuration
 */
export interface MhaPdsMapping {
  MHA_PDS_FIELD_NAME: string;
  MHA_PDS_FIELD_TYPE: string;
  MHA_PDS_VERSIONS: MhaPdsVersion[];
  DESCRIPTION: string;
  FUNCTION: string;
  NOTES: string;
  CODE_SETS: CodeSet[];
  DTAS: DtaReference[];
  TABLES: TableReference[];
  ALPHA_RESONSE_IND: number;
  CONSTANT_IND: number;
  PAIRS: MappingPair[];
}

/**
 * MHA PDS version information
 */
export interface MhaPdsVersion {
  VERSION: string;
}

/**
 * Code set reference
 */
export interface CodeSet {
  CODE_SET_NAME?: string;
  PRIORITY?: number;
}

/**
 * DTA (Discrete Task Assay) reference
 */
export interface DtaReference {
  DTA: string;
  PRIORITY: number;
}

/**
 * Database table reference
 */
export interface TableReference {
  TABLE: string;
  FIELD_NAME: string;
  PRIORITY: number;
}

/**
 * Mapping pair for field value transformations
 */
export interface MappingPair {
  TYPE: string;
  KEY_REF: string;
  KEY_REF_TYPE: string;
  PDS_VALUE: string;
  PDS_VALUE_TYPE: string;
  DISPLAY: string;
  ACTIVE_IND: number;
  PRIORITY: number;
}

/**
 * MHA Location configuration for client discovery
 * Matches CCL structure in gbin_mha_pds_config.prg
 */
export interface MhaLocation {
  LOCATION_NAME: string;      // Display name (e.g., "BriefCounsel-OS")
  FACILITY_CD: number;        // Facility code value
  NURSE_UNIT_CD: number;      // loc_nurse_unit_cd from encounter table
  ACTIVE_IND: number;         // 1 = active/included, 0 = inactive/excluded
}

/**
 * Available location from Cerner for selection in location browser
 */
export interface AvailableLocation {
  LOCATION_CD: number;
  LOCATION_NAME: string;
  LOCATION_MEANING: string;   // NURSEUNIT or AMBULATORY
  FACILITY_CD: number;
  FACILITY_NAME: string;
  BUILDING_CD: number;
  BUILDING_NAME: string;
  IS_MHA_CONFIGURED: number;  // 1 if already in mha_locations
}

/**
 * Main configuration interface for MHA PDS
 * This is the complete structure returned from getMHAPDSConfiguration
 */
export interface MhaPdsConfiguration {
  UPDT_DT_TM: string;
  MIRTH_CONNECT: MirthConnectConfig;
  SUBMISSION: SubmissionConfig;
  PROCESSING: ProcessingConfig;
  CODE_TABLES_CNT: number;
  CODE_TABLES: CodeTable[];
  CODE_TABLE_MAPPING_CNT: number;
  CODE_TABLE_MAPPINGS: CodeTableMapping[];
  MAPPING_CNT: number;
  MAPPINGS: MhaPdsMapping[];
  SUBMIT_FIELDS_CNT: number;
  SUBMIT_FIELDS: SubmitField[];
  FHIR_RESOURCE_CODES_CNT: number;
  FHIR_RESOURCE_CODES: FhirResourceCode[];
  MHA_LOCATIONS_CNT: number;
  MHA_LOCATIONS: MhaLocation[];
}

/**
 * Result type for save operations
 */
export interface SaveResult {
  saved: boolean;
  timestamp: string;
  status: 'S' | 'F';
  errors?: string[];
}

/**
 * Type guard to check if a value is a valid MhaPdsConfiguration
 */
export function isMhaPdsConfiguration(value: unknown): value is MhaPdsConfiguration {
  if (!value || typeof value !== 'object') {
    return false;
  }

  const config = value as Partial<MhaPdsConfiguration>;

  // MHA_LOCATIONS may not exist in older configs - check optionally
  const hasValidMhaLocations = config.MHA_LOCATIONS_CNT === undefined ||
    (typeof config.MHA_LOCATIONS_CNT === 'number' && Array.isArray(config.MHA_LOCATIONS));

  return (
    typeof config.UPDT_DT_TM === 'string' &&
    typeof config.MIRTH_CONNECT === 'object' &&
    typeof config.SUBMISSION === 'object' &&
    typeof config.PROCESSING === 'object' &&
    typeof config.CODE_TABLES_CNT === 'number' &&
    Array.isArray(config.CODE_TABLES) &&
    typeof config.CODE_TABLE_MAPPING_CNT === 'number' &&
    Array.isArray(config.CODE_TABLE_MAPPINGS) &&
    typeof config.MAPPING_CNT === 'number' &&
    Array.isArray(config.MAPPINGS) &&
    typeof config.SUBMIT_FIELDS_CNT === 'number' &&
    Array.isArray(config.SUBMIT_FIELDS) &&
    typeof config.FHIR_RESOURCE_CODES_CNT === 'number' &&
    Array.isArray(config.FHIR_RESOURCE_CODES) &&
    hasValidMhaLocations
  );
}

/**
 * Helper function to get active mappings only
 */
export function getActiveMappings(config: MhaPdsConfiguration): MhaPdsMapping[] {
  return config.MAPPINGS.filter(mapping => mapping.MHA_PDS_FIELD_NAME !== '');
}

/**
 * Helper function to get mapping by field name
 */
export function getMappingByFieldName(
  config: MhaPdsConfiguration,
  fieldName: string
): MhaPdsMapping | undefined {
  return config.MAPPINGS.find(mapping => mapping.MHA_PDS_FIELD_NAME === fieldName);
}

/**
 * Helper function to get active mapping pairs
 */
export function getActiveMappingPairs(mapping: MhaPdsMapping): MappingPair[] {
  return mapping.PAIRS.filter(pair => pair.ACTIVE_IND === 1);
}

/**
 * Helper function to get active submit fields
 */
export function getActiveSubmitFields(config: MhaPdsConfiguration): SubmitField[] {
  return config.SUBMIT_FIELDS.filter(field => field.ACTIVE_IND === 1);
}

/**
 * Helper function to get code table mappings by table ID
 */
export function getCodeTableMappings(
  config: MhaPdsConfiguration,
  codeTableId: string
): CodeTableMapping[] {
  return config.CODE_TABLE_MAPPINGS.filter(mapping => mapping.CODE_TABLE_ID === codeTableId);
}

/**
 * Helper function to get FHIR resource codes by resource type
 */
export function getFhirResourceCodesByType(
  config: MhaPdsConfiguration,
  resourceType: string
): FhirResourceCode[] {
  return config.FHIR_RESOURCE_CODES.filter(code => code.RESOURCE_TYPE === resourceType);
}

/**
 * Helper function to get default FHIR resource code
 */
export function getDefaultFhirResourceCode(
  config: MhaPdsConfiguration,
  resourceType: string,
  fieldName: string
): FhirResourceCode | undefined {
  return config.FHIR_RESOURCE_CODES.find(
    code =>
      code.RESOURCE_TYPE === resourceType && code.FIELD_NAME === fieldName && code.IS_DEFAULT === 1
  );
}

/**
 * Helper function to group mappings by data element (DE01, DE02, etc.)
 */
export function groupMappingsByDataElement(
  config: MhaPdsConfiguration
): Map<string, MhaPdsMapping[]> {
  const groups = new Map<string, MhaPdsMapping[]>();

  config.MAPPINGS.forEach(mapping => {
    if (mapping.MHA_PDS_FIELD_NAME) {
      // Extract DE prefix (e.g., "DE01" from "DE01.001")
      const match = mapping.MHA_PDS_FIELD_NAME.match(/^(DE\d+)/);
      if (match) {
        const deGroup = match[1];
        if (!groups.has(deGroup)) {
          groups.set(deGroup, []);
        }
        groups.get(deGroup)!.push(mapping);
      }
    }
  });

  return groups;
}

/**
 * Helper function to group submit fields by data element
 */
export function groupSubmitFieldsByDataElement(
  config: MhaPdsConfiguration
): Map<string, SubmitField[]> {
  const groups = new Map<string, SubmitField[]>();

  config.SUBMIT_FIELDS.forEach(field => {
    if (field.FIELD_CODE) {
      // Extract DE prefix (e.g., "DE01" from "DE01_001")
      const match = field.FIELD_CODE.match(/^(DE\d+)/);
      if (match) {
        const deGroup = match[1];
        if (!groups.has(deGroup)) {
          groups.set(deGroup, []);
        }
        groups.get(deGroup)!.push(field);
      }
    }
  });

  return groups;
}

/**
 * Constants for MHA PDS data elements
 */
export const MHA_PDS_DATA_ELEMENTS = {
  DE01: 'Client Information',
  DE02: 'Client Identifiers',
  DE03: 'Client Address',
  DE04: 'Client Demographics',
  DE05: 'Referral Information',
  DE06: 'Episode of Care',
  DE07: 'Health Service Provider Organization',
  DE08: 'Health Service Provider Site',
  DE09: 'Health Program',
  DE10: 'Health Service Event'
} as const;

/**
 * Type for data element keys
 */
export type DataElementKey = keyof typeof MHA_PDS_DATA_ELEMENTS;
