import {
  ChangeDetectionStrategy,
  Component,
  Input,
  computed,
  signal
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { CodeTable, CodeTableMapping } from '../../models/mha-pds-configuration.model';

/**
 * Configuration section for code tables (read-only)
 *
 * Displays 32 code tables with 578 mappings
 * Provides search and filter functionality
 */
@Component({
  selector: 'app-config-section-code-tables',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="section-content">
      <!-- Info Banner -->
      <div class="info-banner">
        <span class="info-icon">i</span>
        <span>Code tables are read-only. Contact your system administrator to modify code table mappings.</span>
      </div>

      <!-- Controls -->
      <div class="controls-bar">
        <div class="search-box">
          <input
            type="text"
            placeholder="Search code tables or mappings..."
            class="form-control"
            [ngModel]="searchTerm()"
            (ngModelChange)="searchTerm.set($event)" />
        </div>
        <div class="filter-select">
          <select
            class="form-control"
            [ngModel]="selectedTable()"
            (ngModelChange)="selectedTable.set($event)">
            <option value="">All Code Tables ({{ codeTables.length }})</option>
            @for (table of codeTables; track table.CODE_TABLE_ID) {
              <option [value]="table.CODE_TABLE_ID">
                {{ table.CODE_TABLE_NAME }} ({{ getMappingCountForTable(table.CODE_TABLE_ID) }})
              </option>
            }
          </select>
        </div>
        <div class="stats">
          <span class="stat-item">
            Showing <strong>{{ filteredMappings().length }}</strong> of <strong>{{ codeTableMappings.length }}</strong> mappings
          </span>
        </div>
      </div>

      <!-- Code Table Mappings -->
      <div class="mappings-table-container">
        <table class="mappings-table">
          <thead>
            <tr>
              <th class="col-table">Code Table</th>
              <th class="col-code">Code</th>
              <th class="col-label">Label</th>
              <th class="col-system">Code System</th>
              <th class="col-source">Source</th>
            </tr>
          </thead>
          <tbody>
            @for (mapping of paginatedMappings(); track mapping.CODE_TABLE_ID + '-' + mapping.CODE) {
              <tr>
                <td class="col-table">
                  <span class="table-badge">{{ getTableName(mapping.CODE_TABLE_ID) }}</span>
                </td>
                <td class="col-code">
                  <code>{{ mapping.CODE }}</code>
                </td>
                <td class="col-label">{{ mapping.LABEL }}</td>
                <td class="col-system">
                  @if (mapping.CODE_SYSTEM) {
                    <a [href]="mapping.CODE_SYSTEM" target="_blank" class="system-link">
                      {{ shortenUrl(mapping.CODE_SYSTEM) }}
                    </a>
                  } @else {
                    <span class="no-value">-</span>
                  }
                </td>
                <td class="col-source">
                  @if (mapping.CODE_VALUE_SOURCE) {
                    <span class="source-text">{{ mapping.CODE_VALUE_SOURCE }}</span>
                  } @else {
                    <span class="no-value">-</span>
                  }
                </td>
              </tr>
            }

            @if (filteredMappings().length === 0) {
              <tr>
                <td colspan="5" class="empty-row">
                  No mappings found matching the search criteria
                </td>
              </tr>
            }
          </tbody>
        </table>
      </div>

      <!-- Pagination -->
      @if (totalPages() > 1) {
        <div class="pagination">
          <button
            class="btn-page"
            [disabled]="currentPage() === 1"
            (click)="goToPage(1)">
            First
          </button>
          <button
            class="btn-page"
            [disabled]="currentPage() === 1"
            (click)="goToPage(currentPage() - 1)">
            Previous
          </button>
          <span class="page-info">
            Page {{ currentPage() }} of {{ totalPages() }}
          </span>
          <button
            class="btn-page"
            [disabled]="currentPage() === totalPages()"
            (click)="goToPage(currentPage() + 1)">
            Next
          </button>
          <button
            class="btn-page"
            [disabled]="currentPage() === totalPages()"
            (click)="goToPage(totalPages())">
            Last
          </button>
        </div>
      }
    </div>
  `,
  styles: [`
    .section-content {
      max-width: 1200px;
    }

    .info-banner {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 12px 16px;
      background-color: #e7f3ff;
      border: 1px solid #b3d9ff;
      border-radius: 6px;
      margin-bottom: 20px;
      color: #0056b3;
      font-size: 13px;

      .info-icon {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 20px;
        height: 20px;
        background-color: #0078d4;
        color: white;
        border-radius: 50%;
        font-size: 12px;
        font-weight: bold;
        flex-shrink: 0;
      }
    }

    .controls-bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 16px;
      margin-bottom: 20px;
      padding: 12px 16px;
      background-color: #f8f9fa;
      border: 1px solid #e9ecef;
      border-radius: 6px;

      .search-box {
        flex: 1;
        min-width: 200px;
      }

      .filter-select {
        min-width: 250px;
      }

      .form-control {
        width: 100%;
        padding: 8px 12px;
        border: 1px solid #ced4da;
        border-radius: 4px;
        font-size: 14px;

        &:focus {
          outline: none;
          border-color: #0078d4;
          box-shadow: 0 0 0 2px rgba(0, 120, 212, 0.1);
        }
      }

      select.form-control {
        cursor: pointer;
        background-color: white;
      }

      .stats {
        .stat-item {
          font-size: 13px;
          color: #555;
        }
      }
    }

    .mappings-table-container {
      overflow-x: auto;
      border: 1px solid #dee2e6;
      border-radius: 6px;
    }

    .mappings-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;

      th, td {
        padding: 10px 12px;
        text-align: left;
        border-bottom: 1px solid #e9ecef;
      }

      thead {
        background-color: #f8f9fa;

        th {
          font-weight: 600;
          color: #333;
          white-space: nowrap;
        }
      }

      tbody tr {
        &:hover {
          background-color: #f8f9fa;
        }

        &:last-child td {
          border-bottom: none;
        }
      }

      .col-table { width: 180px; }
      .col-code { width: 120px; }
      .col-label { min-width: 200px; }
      .col-system { width: 200px; }
      .col-source { width: 150px; }

      .table-badge {
        display: inline-block;
        padding: 4px 8px;
        background-color: #e9ecef;
        border-radius: 4px;
        font-size: 11px;
        font-weight: 500;
        color: #495057;
        max-width: 160px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      code {
        padding: 2px 6px;
        background-color: #f5f5f5;
        border-radius: 3px;
        font-family: monospace;
        font-size: 12px;
        color: #d73a49;
      }

      .system-link {
        color: #0078d4;
        text-decoration: none;
        font-size: 12px;

        &:hover {
          text-decoration: underline;
        }
      }

      .source-text {
        font-size: 12px;
        color: #555;
      }

      .no-value {
        color: #adb5bd;
      }

      .empty-row {
        text-align: center;
        color: #6c757d;
        padding: 40px;
        font-style: italic;
      }
    }

    .pagination {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      margin-top: 20px;
      padding: 16px;

      .btn-page {
        padding: 6px 12px;
        border: 1px solid #ced4da;
        background-color: white;
        border-radius: 4px;
        font-size: 13px;
        cursor: pointer;
        transition: all 0.2s;

        &:hover:not(:disabled) {
          background-color: #f8f9fa;
          border-color: #adb5bd;
        }

        &:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }
      }

      .page-info {
        padding: 0 12px;
        font-size: 13px;
        color: #555;
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfigSectionCodeTables {
  @Input() codeTables: CodeTable[] = [];
  @Input() codeTableMappings: CodeTableMapping[] = [];

  // UI state
  searchTerm = signal('');
  selectedTable = signal('');
  currentPage = signal(1);
  readonly pageSize = 25;

  // Computed values
  filteredMappings = computed(() => {
    const term = this.searchTerm().toLowerCase();
    const tableId = this.selectedTable();

    return this.codeTableMappings.filter(mapping => {
      // Filter by table
      if (tableId && mapping.CODE_TABLE_ID !== tableId) {
        return false;
      }

      // Filter by search term
      if (term) {
        const tableName = this.getTableName(mapping.CODE_TABLE_ID).toLowerCase();
        return (
          mapping.CODE.toLowerCase().includes(term) ||
          mapping.LABEL.toLowerCase().includes(term) ||
          mapping.DESCRIPTION.toLowerCase().includes(term) ||
          tableName.includes(term)
        );
      }

      return true;
    });
  });

  totalPages = computed(() => {
    return Math.ceil(this.filteredMappings().length / this.pageSize) || 1;
  });

  paginatedMappings = computed(() => {
    const start = (this.currentPage() - 1) * this.pageSize;
    const end = start + this.pageSize;
    return this.filteredMappings().slice(start, end);
  });

  getMappingCountForTable(tableId: string): number {
    return this.codeTableMappings.filter(m => m.CODE_TABLE_ID === tableId).length;
  }

  getTableName(tableId: string): string {
    const table = this.codeTables.find(t => t.CODE_TABLE_ID === tableId);
    return table?.CODE_TABLE_NAME || tableId;
  }

  shortenUrl(url: string): string {
    try {
      const parsed = new URL(url);
      const path = parsed.pathname.split('/').pop() || '';
      return path || parsed.hostname;
    } catch {
      return url.length > 30 ? url.substring(0, 30) + '...' : url;
    }
  }

  goToPage(page: number): void {
    if (page >= 1 && page <= this.totalPages()) {
      this.currentPage.set(page);
    }
  }
}
