import {
  ChangeDetectionStrategy,
  Component,
  Input,
  computed,
  signal
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { FhirResourceCode } from '../../models/mha-pds-configuration.model';

/**
 * Configuration section for FHIR resource codes (read-only)
 *
 * Displays 12 mandatory FHIR codes for resource defaults
 */
@Component({
  selector: 'app-config-section-fhir-codes',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="section-content">
      <!-- Info Banner -->
      <div class="info-banner">
        <span class="info-icon">i</span>
        <span>FHIR resource codes are read-only. These are mandatory default values used when building FHIR resources for MHA PDS submissions.</span>
      </div>

      <!-- Filter by Resource Type -->
      <div class="controls-bar">
        <div class="filter-select">
          <select
            class="form-control"
            [ngModel]="selectedResourceType()"
            (ngModelChange)="selectedResourceType.set($event)">
            <option value="">All Resource Types ({{ fhirCodes.length }})</option>
            @for (type of resourceTypes(); track type) {
              <option [value]="type">{{ type }} ({{ getCountForType(type) }})</option>
            }
          </select>
        </div>
        <div class="stats">
          <span class="stat-item">
            Showing <strong>{{ filteredCodes().length }}</strong> of <strong>{{ fhirCodes.length }}</strong> codes
          </span>
        </div>
      </div>

      <!-- FHIR Codes Table -->
      <div class="codes-table-container">
        <table class="codes-table">
          <thead>
            <tr>
              <th class="col-resource">Resource Type</th>
              <th class="col-field">Field Name</th>
              <th class="col-code">Code</th>
              <th class="col-label">Label</th>
              <th class="col-system">Code System</th>
              <th class="col-default">Default</th>
            </tr>
          </thead>
          <tbody>
            @for (code of filteredCodes(); track code.RESOURCE_TYPE + '-' + code.FIELD_NAME + '-' + code.CODE) {
              <tr [class.is-default]="code.IS_DEFAULT === 1">
                <td class="col-resource">
                  <span class="resource-badge">{{ code.RESOURCE_TYPE }}</span>
                </td>
                <td class="col-field">{{ code.FIELD_NAME }}</td>
                <td class="col-code">
                  <code>{{ code.CODE }}</code>
                </td>
                <td class="col-label">{{ code.LABEL }}</td>
                <td class="col-system">
                  @if (code.CODE_SYSTEM) {
                    <a [href]="code.CODE_SYSTEM" target="_blank" class="system-link" [title]="code.CODE_SYSTEM">
                      {{ shortenUrl(code.CODE_SYSTEM) }}
                    </a>
                  } @else {
                    <span class="no-value">-</span>
                  }
                </td>
                <td class="col-default">
                  @if (code.IS_DEFAULT === 1) {
                    <span class="default-badge">Default</span>
                  } @else {
                    <span class="no-value">-</span>
                  }
                </td>
              </tr>
            }

            @if (filteredCodes().length === 0) {
              <tr>
                <td colspan="6" class="empty-row">
                  No FHIR codes found for the selected resource type
                </td>
              </tr>
            }
          </tbody>
        </table>
      </div>

      <!-- Resource Type Summary -->
      <div class="resource-summary">
        <h4>Resource Type Summary</h4>
        <div class="summary-grid">
          @for (type of resourceTypes(); track type) {
            <div class="summary-card">
              <div class="summary-type">{{ type }}</div>
              <div class="summary-count">{{ getCountForType(type) }} codes</div>
              <div class="summary-fields">
                @for (field of getFieldsForType(type); track field) {
                  <span class="field-tag">{{ field }}</span>
                }
              </div>
            </div>
          }
        </div>
      </div>
    </div>
  `,
  styles: [`
    .section-content {
      max-width: 1200px;
    }

    .info-banner {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 12px 16px;
      background-color: #e7f3ff;
      border: 1px solid #b3d9ff;
      border-radius: 6px;
      margin-bottom: 20px;
      color: #0056b3;
      font-size: 13px;

      .info-icon {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 20px;
        height: 20px;
        background-color: #0078d4;
        color: white;
        border-radius: 50%;
        font-size: 12px;
        font-weight: bold;
        flex-shrink: 0;
      }
    }

    .controls-bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 16px;
      margin-bottom: 20px;
      padding: 12px 16px;
      background-color: #f8f9fa;
      border: 1px solid #e9ecef;
      border-radius: 6px;

      .filter-select {
        min-width: 250px;
      }

      .form-control {
        width: 100%;
        padding: 8px 12px;
        border: 1px solid #ced4da;
        border-radius: 4px;
        font-size: 14px;
        cursor: pointer;
        background-color: white;

        &:focus {
          outline: none;
          border-color: #0078d4;
          box-shadow: 0 0 0 2px rgba(0, 120, 212, 0.1);
        }
      }

      .stats {
        margin-left: auto;

        .stat-item {
          font-size: 13px;
          color: #555;
        }
      }
    }

    .codes-table-container {
      overflow-x: auto;
      border: 1px solid #dee2e6;
      border-radius: 6px;
    }

    .codes-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;

      th, td {
        padding: 10px 12px;
        text-align: left;
        border-bottom: 1px solid #e9ecef;
      }

      thead {
        background-color: #f8f9fa;

        th {
          font-weight: 600;
          color: #333;
          white-space: nowrap;
        }
      }

      tbody tr {
        &:hover {
          background-color: #f8f9fa;
        }

        &:last-child td {
          border-bottom: none;
        }

        &.is-default {
          background-color: #f0fff4;
        }
      }

      .col-resource { width: 140px; }
      .col-field { width: 120px; }
      .col-code { width: 100px; }
      .col-label { min-width: 150px; }
      .col-system { width: 200px; }
      .col-default { width: 80px; }

      .resource-badge {
        display: inline-block;
        padding: 4px 8px;
        background-color: #e7f3ff;
        border: 1px solid #b3d9ff;
        border-radius: 4px;
        font-size: 11px;
        font-weight: 600;
        color: #0056b3;
      }

      code {
        padding: 2px 6px;
        background-color: #f5f5f5;
        border-radius: 3px;
        font-family: monospace;
        font-size: 12px;
        color: #d73a49;
      }

      .system-link {
        color: #0078d4;
        text-decoration: none;
        font-size: 12px;

        &:hover {
          text-decoration: underline;
        }
      }

      .no-value {
        color: #adb5bd;
      }

      .default-badge {
        display: inline-block;
        padding: 3px 8px;
        background-color: #d4edda;
        color: #155724;
        border-radius: 3px;
        font-size: 10px;
        font-weight: 600;
      }

      .empty-row {
        text-align: center;
        color: #6c757d;
        padding: 40px;
        font-style: italic;
      }
    }

    .resource-summary {
      margin-top: 24px;
      padding: 16px;
      background-color: #f8f9fa;
      border: 1px solid #e9ecef;
      border-radius: 6px;

      h4 {
        margin: 0 0 16px 0;
        color: #333;
        font-size: 14px;
        font-weight: 600;
      }

      .summary-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: 12px;
      }

      .summary-card {
        padding: 12px;
        background-color: white;
        border: 1px solid #dee2e6;
        border-radius: 6px;

        .summary-type {
          font-weight: 600;
          color: #0078d4;
          font-size: 14px;
          margin-bottom: 4px;
        }

        .summary-count {
          font-size: 12px;
          color: #6c757d;
          margin-bottom: 8px;
        }

        .summary-fields {
          display: flex;
          flex-wrap: wrap;
          gap: 4px;

          .field-tag {
            padding: 2px 6px;
            background-color: #e9ecef;
            border-radius: 3px;
            font-size: 11px;
            color: #495057;
          }
        }
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfigSectionFhirCodes {
  @Input() fhirCodes: FhirResourceCode[] = [];

  // UI state
  selectedResourceType = signal('');

  // Computed values
  resourceTypes = computed(() => {
    const types = new Set(this.fhirCodes.map(c => c.RESOURCE_TYPE));
    return Array.from(types).sort();
  });

  filteredCodes = computed(() => {
    const type = this.selectedResourceType();
    if (!type) return this.fhirCodes;
    return this.fhirCodes.filter(c => c.RESOURCE_TYPE === type);
  });

  getCountForType(type: string): number {
    return this.fhirCodes.filter(c => c.RESOURCE_TYPE === type).length;
  }

  getFieldsForType(type: string): string[] {
    const fields = new Set(
      this.fhirCodes
        .filter(c => c.RESOURCE_TYPE === type)
        .map(c => c.FIELD_NAME)
    );
    return Array.from(fields);
  }

  shortenUrl(url: string): string {
    try {
      const parsed = new URL(url);
      const path = parsed.pathname.split('/').pop() || '';
      return path || parsed.hostname;
    } catch {
      return url.length > 30 ? url.substring(0, 30) + '...' : url;
    }
  }
}
