import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Input,
  Output,
  computed,
  signal
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { SubmitField, MHA_PDS_DATA_ELEMENTS, DataElementKey } from '../../models/mha-pds-configuration.model';

/**
 * Configuration section for submit fields
 *
 * Displays 68 data element fields grouped by category (DE01-DE10)
 * Allows toggling each field's active status
 */
@Component({
  selector: 'app-config-section-submit-fields',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="section-content">
      <!-- Controls -->
      <div class="controls-bar">
        <div class="search-box">
          <input
            type="text"
            placeholder="Search fields..."
            class="form-control"
            [ngModel]="searchTerm()"
            (ngModelChange)="searchTerm.set($event)" />
        </div>
        <div class="bulk-actions">
          <button class="btn btn-small btn-outline" (click)="enableAll()">Enable All</button>
          <button class="btn btn-small btn-outline" (click)="disableAll()">Disable All</button>
        </div>
        <div class="stats">
          <span class="stat-item">
            <strong>{{ activeCount() }}</strong> of <strong>{{ totalCount() }}</strong> active
          </span>
        </div>
      </div>

      <!-- Field Groups -->
      <div class="field-groups">
        @for (entry of sortedCategories(); track entry.key) {
          <div class="field-group" [class.collapsed]="collapsedGroups()[entry.key]">
            <div class="group-header" (click)="toggleGroup(entry.key)">
              <div class="group-title">
                <span class="expand-icon">{{ collapsedGroups()[entry.key] ? '+' : '-' }}</span>
                <h4>{{ entry.key }}: {{ getDataElementLabel(entry.key) }}</h4>
              </div>
              <div class="group-stats">
                <span class="active-count">
                  {{ getActiveCountForGroup(entry.key) }}/{{ entry.fields.length }} active
                </span>
              </div>
            </div>

            @if (!collapsedGroups()[entry.key]) {
              <div class="group-content">
                @for (field of filterFields(entry.fields); track field.FIELD_CODE) {
                  <div class="field-item" [class.active]="field.ACTIVE_IND === 1">
                    <label class="field-checkbox">
                      <input
                        type="checkbox"
                        [checked]="field.ACTIVE_IND === 1"
                        (change)="onFieldToggle(field, $event)" />
                      <span class="checkmark"></span>
                    </label>
                    <div class="field-info">
                      <span class="field-code">{{ field.FIELD_CODE }}</span>
                      <span class="field-description">{{ field.DESCRIPTION }}</span>
                    </div>
                  </div>
                }

                @if (filterFields(entry.fields).length === 0) {
                  <div class="no-results">No fields match the search criteria</div>
                }
              </div>
            }
          </div>
        }
      </div>

      @if (sortedCategories().length === 0) {
        <div class="empty-state">
          <p>No submit fields configured</p>
        </div>
      }
    </div>
  `,
  styles: [`
    .section-content {
      max-width: 1000px;
    }

    .controls-bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 16px;
      margin-bottom: 20px;
      padding: 12px 16px;
      background-color: #f8f9fa;
      border: 1px solid #e9ecef;
      border-radius: 6px;

      .search-box {
        flex: 1;
        min-width: 200px;

        .form-control {
          width: 100%;
          padding: 8px 12px;
          border: 1px solid #ced4da;
          border-radius: 4px;
          font-size: 14px;

          &:focus {
            outline: none;
            border-color: #0078d4;
            box-shadow: 0 0 0 2px rgba(0, 120, 212, 0.1);
          }
        }
      }

      .bulk-actions {
        display: flex;
        gap: 8px;
      }

      .stats {
        .stat-item {
          font-size: 13px;
          color: #555;
        }
      }
    }

    .btn-small {
      padding: 6px 12px;
      font-size: 12px;
      border-radius: 4px;
      cursor: pointer;
      transition: all 0.2s;
    }

    .btn-outline {
      background: white;
      border: 1px solid #ced4da;
      color: #333;

      &:hover {
        background-color: #f8f9fa;
        border-color: #adb5bd;
      }
    }

    .field-groups {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .field-group {
      border: 1px solid #dee2e6;
      border-radius: 8px;
      overflow: hidden;

      &.collapsed {
        .group-header {
          border-radius: 8px;
        }
      }
    }

    .group-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 12px 16px;
      background-color: #f8f9fa;
      cursor: pointer;
      user-select: none;
      transition: background-color 0.2s;

      &:hover {
        background-color: #e9ecef;
      }

      .group-title {
        display: flex;
        align-items: center;
        gap: 10px;

        .expand-icon {
          width: 20px;
          height: 20px;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 16px;
          font-weight: bold;
          color: #6c757d;
        }

        h4 {
          margin: 0;
          color: #333;
          font-size: 14px;
          font-weight: 600;
        }
      }

      .group-stats {
        .active-count {
          font-size: 12px;
          color: #6c757d;
          padding: 4px 8px;
          background-color: white;
          border-radius: 12px;
        }
      }
    }

    .group-content {
      padding: 12px;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 8px;
    }

    .field-item {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 12px;
      background-color: #fff;
      border: 1px solid #e9ecef;
      border-radius: 4px;
      transition: all 0.2s;

      &:hover {
        background-color: #f8f9fa;
        border-color: #dee2e6;
      }

      &.active {
        background-color: #e7f3ff;
        border-color: #b3d9ff;
      }

      .field-checkbox {
        position: relative;
        width: 20px;
        height: 20px;
        flex-shrink: 0;

        input {
          position: absolute;
          opacity: 0;
          cursor: pointer;
          width: 100%;
          height: 100%;
          margin: 0;
          z-index: 1;

          &:checked ~ .checkmark {
            background-color: #0078d4;
            border-color: #0078d4;

            &:after {
              display: block;
            }
          }
        }

        .checkmark {
          position: absolute;
          top: 0;
          left: 0;
          width: 20px;
          height: 20px;
          background-color: white;
          border: 2px solid #ced4da;
          border-radius: 4px;
          transition: all 0.2s;

          &:after {
            content: "";
            position: absolute;
            display: none;
            left: 6px;
            top: 2px;
            width: 5px;
            height: 10px;
            border: solid white;
            border-width: 0 2px 2px 0;
            transform: rotate(45deg);
          }
        }
      }

      .field-info {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 2px;
        min-width: 0;

        .field-code {
          font-size: 12px;
          font-weight: 600;
          color: #0078d4;
          font-family: monospace;
        }

        .field-description {
          font-size: 13px;
          color: #333;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
      }
    }

    .no-results {
      grid-column: 1 / -1;
      padding: 20px;
      text-align: center;
      color: #6c757d;
      font-size: 14px;
    }

    .empty-state {
      padding: 40px;
      text-align: center;
      color: #6c757d;

      p {
        margin: 0;
        font-size: 14px;
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfigSectionSubmitFields {
  @Input() fields: SubmitField[] = [];
  @Input() fieldsByCategory: Map<string, SubmitField[]> = new Map();
  @Output() fieldsChange = new EventEmitter<SubmitField[]>();

  // UI state
  searchTerm = signal('');
  collapsedGroups = signal<Record<string, boolean>>({});

  // Data element labels
  readonly DATA_ELEMENT_LABELS = MHA_PDS_DATA_ELEMENTS;

  // Computed values
  sortedCategories = computed(() => {
    const entries = Array.from(this.fieldsByCategory.entries())
      .map(([key, fields]) => ({ key, fields }))
      .sort((a, b) => a.key.localeCompare(b.key));
    return entries;
  });

  activeCount = computed(() => {
    return this.fields.filter(f => f.ACTIVE_IND === 1).length;
  });

  totalCount = computed(() => {
    return this.fields.length;
  });

  getDataElementLabel(key: string): string {
    return this.DATA_ELEMENT_LABELS[key as DataElementKey] || key;
  }

  getActiveCountForGroup(key: string): number {
    const fields = this.fieldsByCategory.get(key) || [];
    return fields.filter(f => f.ACTIVE_IND === 1).length;
  }

  toggleGroup(key: string): void {
    this.collapsedGroups.update(groups => ({
      ...groups,
      [key]: !groups[key]
    }));
  }

  filterFields(fields: SubmitField[]): SubmitField[] {
    const term = this.searchTerm().toLowerCase();
    if (!term) return fields;
    return fields.filter(f =>
      f.FIELD_CODE.toLowerCase().includes(term) ||
      f.DESCRIPTION.toLowerCase().includes(term)
    );
  }

  onFieldToggle(field: SubmitField, event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    const updatedFields = this.fields.map(f =>
      f.FIELD_CODE === field.FIELD_CODE
        ? { ...f, ACTIVE_IND: checked ? 1 : 0 }
        : f
    );
    this.fieldsChange.emit(updatedFields);
  }

  enableAll(): void {
    const updatedFields = this.fields.map(f => ({ ...f, ACTIVE_IND: 1 }));
    this.fieldsChange.emit(updatedFields);
  }

  disableAll(): void {
    const updatedFields = this.fields.map(f => ({ ...f, ACTIVE_IND: 0 }));
    this.fieldsChange.emit(updatedFields);
  }
}
