import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Input,
  Output
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ProcessingConfig } from '../../models/mha-pds-configuration.model';

/**
 * Configuration section for processing flags
 *
 * Allows toggling of:
 * - Dummy mode (test without sending data)
 * - Detailed logging
 * - Error notifications
 */
@Component({
  selector: 'app-config-section-processing',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="section-content">
      <div class="toggle-list">
        <!-- Dummy Mode -->
        <div class="toggle-item" [class.enabled]="config.ENABLE_DUMMY_MODE === 1">
          <div class="toggle-info">
            <h4>Dummy Mode</h4>
            <p>When enabled, the system processes data without actually submitting to Mirth Connect. Useful for testing and validation.</p>
            @if (config.ENABLE_DUMMY_MODE === 1) {
              <div class="warning-badge">
                <span>Warning: Data will NOT be submitted to external systems</span>
              </div>
            }
          </div>
          <label class="toggle-switch">
            <input
              type="checkbox"
              [checked]="config.ENABLE_DUMMY_MODE === 1"
              (change)="onToggleChange('ENABLE_DUMMY_MODE', $event)" />
            <span class="toggle-slider"></span>
          </label>
        </div>

        <!-- Detailed Logging -->
        <div class="toggle-item" [class.enabled]="config.ENABLE_DETAILED_LOGGING === 1">
          <div class="toggle-info">
            <h4>Detailed Logging</h4>
            <p>Enables verbose logging of all processing steps, including data transformations and API calls. Helpful for debugging but may impact performance.</p>
          </div>
          <label class="toggle-switch">
            <input
              type="checkbox"
              [checked]="config.ENABLE_DETAILED_LOGGING === 1"
              (change)="onToggleChange('ENABLE_DETAILED_LOGGING', $event)" />
            <span class="toggle-slider"></span>
          </label>
        </div>

        <!-- Error Notifications -->
        <div class="toggle-item" [class.enabled]="config.ENABLE_ERROR_NOTIFICATIONS === 1">
          <div class="toggle-info">
            <h4>Error Notifications</h4>
            <p>Sends notifications when submission errors occur. Configure notification recipients in the system settings.</p>
          </div>
          <label class="toggle-switch">
            <input
              type="checkbox"
              [checked]="config.ENABLE_ERROR_NOTIFICATIONS === 1"
              (change)="onToggleChange('ENABLE_ERROR_NOTIFICATIONS', $event)" />
            <span class="toggle-slider"></span>
          </label>
        </div>
      </div>

      <!-- Status Summary -->
      <div class="status-summary">
        <h4>Current Status</h4>
        <div class="status-grid">
          <div class="status-item">
            <span class="status-label">Mode:</span>
            <span class="status-value" [class.warning]="config.ENABLE_DUMMY_MODE === 1">
              {{ config.ENABLE_DUMMY_MODE === 1 ? 'Test (Dummy)' : 'Production' }}
            </span>
          </div>
          <div class="status-item">
            <span class="status-label">Logging:</span>
            <span class="status-value">
              {{ config.ENABLE_DETAILED_LOGGING === 1 ? 'Verbose' : 'Standard' }}
            </span>
          </div>
          <div class="status-item">
            <span class="status-label">Notifications:</span>
            <span class="status-value">
              {{ config.ENABLE_ERROR_NOTIFICATIONS === 1 ? 'Enabled' : 'Disabled' }}
            </span>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .section-content {
      max-width: 800px;
    }

    .toggle-list {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .toggle-item {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 20px;
      padding: 20px;
      background-color: #f8f9fa;
      border: 1px solid #e9ecef;
      border-radius: 8px;
      transition: all 0.2s ease;

      &.enabled {
        background-color: #e7f3ff;
        border-color: #b3d9ff;
      }

      .toggle-info {
        flex: 1;

        h4 {
          margin: 0 0 6px 0;
          color: #333;
          font-size: 15px;
          font-weight: 600;
        }

        p {
          margin: 0;
          color: #555;
          font-size: 13px;
          line-height: 1.5;
        }

        .warning-badge {
          margin-top: 10px;
          padding: 8px 12px;
          background-color: #fff3cd;
          border: 1px solid #ffc107;
          border-radius: 4px;

          span {
            color: #856404;
            font-size: 12px;
            font-weight: 500;
          }
        }
      }
    }

    .toggle-switch {
      position: relative;
      display: inline-block;
      width: 50px;
      height: 26px;
      flex-shrink: 0;

      input {
        opacity: 0;
        width: 0;
        height: 0;

        &:checked + .toggle-slider {
          background-color: #0078d4;
        }

        &:checked + .toggle-slider:before {
          transform: translateX(24px);
        }

        &:focus + .toggle-slider {
          box-shadow: 0 0 0 3px rgba(0, 120, 212, 0.2);
        }
      }

      .toggle-slider {
        position: absolute;
        cursor: pointer;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: #ccc;
        border-radius: 26px;
        transition: 0.3s;

        &:before {
          position: absolute;
          content: "";
          height: 20px;
          width: 20px;
          left: 3px;
          bottom: 3px;
          background-color: white;
          border-radius: 50%;
          transition: 0.3s;
        }
      }
    }

    .status-summary {
      margin-top: 24px;
      padding: 16px;
      background-color: #fff;
      border: 1px solid #dee2e6;
      border-radius: 6px;

      h4 {
        margin: 0 0 12px 0;
        color: #333;
        font-size: 14px;
        font-weight: 600;
      }

      .status-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 16px;

        @media (max-width: 600px) {
          grid-template-columns: 1fr;
        }
      }

      .status-item {
        display: flex;
        flex-direction: column;
        gap: 4px;

        .status-label {
          color: #6c757d;
          font-size: 12px;
          font-weight: 500;
        }

        .status-value {
          color: #333;
          font-size: 14px;
          font-weight: 600;

          &.warning {
            color: #856404;
          }
        }
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfigSectionProcessing {
  @Input() config!: ProcessingConfig;
  @Output() configChange = new EventEmitter<ProcessingConfig>();

  onToggleChange(field: keyof ProcessingConfig, event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    const updatedConfig = { ...this.config, [field]: checked ? 1 : 0 };
    this.configChange.emit(updatedConfig);
  }
}
