import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  signal,
  OnInit
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MhaPdsConfigurationService } from '../services/mha-pds-configuration.service';
import {
  MhaPdsConfiguration,
  MirthConnectConfig,
  SubmissionConfig,
  ProcessingConfig,
  SubmitField,
  MhaPdsMapping,
  CodeTable,
  CodeTableMapping,
  FhirResourceCode,
  MhaLocation,
  MHA_PDS_DATA_ELEMENTS,
  DataElementKey,
  groupSubmitFieldsByDataElement
} from '../models/mha-pds-configuration.model';

// Section Components
import { ConfigSectionMirth } from './sections/config-section-mirth';
import { ConfigSectionSubmission } from './sections/config-section-submission';
import { ConfigSectionProcessing } from './sections/config-section-processing';
import { ConfigSectionSubmitFields } from './sections/config-section-submit-fields';
import { ConfigSectionCodeTables } from './sections/config-section-code-tables';
import { ConfigSectionMappings } from './sections/config-section-mappings';
import { ConfigSectionFhirCodes } from './sections/config-section-fhir-codes';
import { ConfigSectionMhaLocations } from './sections/config-section-mha-locations';

/**
 * Tab definitions for the configuration editor
 */
type ConfigTab = 'mirth' | 'submission' | 'processing' | 'submit_fields' | 'code_tables' | 'mappings' | 'fhir_codes' | 'mha_locations';

interface TabInfo {
  id: ConfigTab;
  label: string;
  icon: string;
  description: string;
  editable: boolean;
}

/**
 * Configuration Editor Component
 *
 * Provides a comprehensive UI for viewing and editing MHA PDS configuration settings.
 * Supports tab-based navigation between different configuration sections:
 * - Mirth Connect: Server connection settings
 * - Submission: Batch size, schedule, retries
 * - Processing: Operational flags
 * - Submit Fields: 68 data element toggles grouped by category
 * - Code Tables: 32 code tables with 578 mappings (read-only)
 * - Mappings: 48 field mappings with pairs
 * - FHIR Resource Codes: 12 mandatory codes (read-only)
 */
@Component({
  selector: 'app-config-editor',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ConfigSectionMirth,
    ConfigSectionSubmission,
    ConfigSectionProcessing,
    ConfigSectionSubmitFields,
    ConfigSectionCodeTables,
    ConfigSectionMappings,
    ConfigSectionFhirCodes,
    ConfigSectionMhaLocations
  ],
  templateUrl: './config-editor.html',
  styleUrl: './config-editor.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfigEditorComponent implements OnInit {
  private configService = inject(MhaPdsConfigurationService);

  // Configuration state
  config = signal<MhaPdsConfiguration | null>(null);
  originalConfig = signal<MhaPdsConfiguration | null>(null);

  // UI state
  loading = signal(false);
  saving = signal(false);
  activeTab = signal<ConfigTab>('mirth');
  hasChanges = signal(false);

  // Notification state
  notification = signal<{type: 'success' | 'error' | 'info'; message: string} | null>(null);

  // Tab configuration
  readonly tabs: TabInfo[] = [
    { id: 'mirth', label: 'Mirth Connect', icon: 'server', description: 'Server connection settings', editable: true },
    { id: 'submission', label: 'Submission', icon: 'send', description: 'Batch size, schedule, retries', editable: true },
    { id: 'processing', label: 'Processing', icon: 'settings', description: 'Operational flags', editable: true },
    { id: 'submit_fields', label: 'Submit Fields', icon: 'list', description: '68 data element toggles', editable: true },
    { id: 'code_tables', label: 'Code Tables', icon: 'table', description: '32 code tables (read-only)', editable: false },
    { id: 'mappings', label: 'Mappings', icon: 'link', description: '48 field mappings', editable: true },
    { id: 'fhir_codes', label: 'FHIR Codes', icon: 'code', description: '12 FHIR codes (read-only)', editable: false },
    { id: 'mha_locations', label: 'MHA Locations', icon: 'location', description: 'Patient discovery locations', editable: true }
  ];

  // Computed signals for config sections
  mirthConfig = computed(() => this.config()?.MIRTH_CONNECT ?? null);
  submissionConfig = computed(() => this.config()?.SUBMISSION ?? null);
  processingConfig = computed(() => this.config()?.PROCESSING ?? null);
  submitFields = computed(() => this.config()?.SUBMIT_FIELDS ?? []);
  codeTables = computed(() => this.config()?.CODE_TABLES ?? []);
  codeTableMappings = computed(() => this.config()?.CODE_TABLE_MAPPINGS ?? []);
  mappings = computed(() => this.config()?.MAPPINGS ?? []);
  fhirResourceCodes = computed(() => this.config()?.FHIR_RESOURCE_CODES ?? []);
  mhaLocations = computed(() => this.config()?.MHA_LOCATIONS ?? []);

  // Group submit fields by data element category
  submitFieldsByCategory = computed(() => {
    const config = this.config();
    if (!config) return new Map<string, SubmitField[]>();
    return groupSubmitFieldsByDataElement(config);
  });

  // Data element labels for display
  readonly DATA_ELEMENT_LABELS = MHA_PDS_DATA_ELEMENTS;

  // Stats for display
  configStats = computed(() => {
    const config = this.config();
    if (!config) return null;
    return {
      codeTables: config.CODE_TABLES_CNT,
      codeTableMappings: config.CODE_TABLE_MAPPING_CNT,
      mappings: config.MAPPING_CNT,
      submitFields: config.SUBMIT_FIELDS_CNT,
      fhirCodes: config.FHIR_RESOURCE_CODES_CNT,
      lastUpdated: config.UPDT_DT_TM
    };
  });

  constructor() {
    // Clear notification after 5 seconds
    effect(() => {
      const notif = this.notification();
      if (notif) {
        setTimeout(() => {
          this.notification.set(null);
        }, 5000);
      }
    });
  }

  ngOnInit(): void {
    this.loadConfiguration();
  }

  /**
   * Load configuration from the service
   */
  loadConfiguration(): void {
    this.loading.set(true);
    this.notification.set(null);

    this.configService.getConfiguration().subscribe({
      next: (config) => {
        this.config.set(config);
        this.originalConfig.set(JSON.parse(JSON.stringify(config))); // Deep clone
        this.hasChanges.set(false);
        this.loading.set(false);
        this.showNotification('success', 'Configuration loaded successfully');
      },
      error: (error) => {
        this.loading.set(false);
        this.showNotification('error', `Failed to load configuration: ${error.message}`);
        console.error('[ConfigEditor] Error loading configuration:', error);
      }
    });
  }

  /**
   * Save configuration changes
   */
  saveConfiguration(): void {
    const config = this.config();
    if (!config) {
      this.showNotification('error', 'No configuration to save');
      return;
    }

    this.saving.set(true);
    this.notification.set(null);

    this.configService.saveConfiguration(config).subscribe({
      next: (result) => {
        this.saving.set(false);
        if (result.saved) {
          this.originalConfig.set(JSON.parse(JSON.stringify(config)));
          this.hasChanges.set(false);
          this.showNotification('success', 'Configuration saved successfully');
        } else {
          const errors = result.errors?.join(', ') || 'Unknown error';
          this.showNotification('error', `Failed to save configuration: ${errors}`);
        }
      },
      error: (error) => {
        this.saving.set(false);
        this.showNotification('error', `Failed to save configuration: ${error.message}`);
        console.error('[ConfigEditor] Error saving configuration:', error);
      }
    });
  }

  /**
   * Discard changes and reload original configuration
   */
  discardChanges(): void {
    const original = this.originalConfig();
    if (original) {
      this.config.set(JSON.parse(JSON.stringify(original)));
      this.hasChanges.set(false);
      this.showNotification('info', 'Changes discarded');
    }
  }

  /**
   * Refresh configuration from the server
   */
  refreshConfiguration(): void {
    if (this.hasChanges()) {
      if (!confirm('You have unsaved changes. Refresh will discard them. Continue?')) {
        return;
      }
    }
    this.loadConfiguration();
  }

  /**
   * Handle tab change
   */
  setActiveTab(tab: ConfigTab): void {
    this.activeTab.set(tab);
  }

  /**
   * Handle Mirth config changes
   */
  onMirthConfigChange(mirthConfig: MirthConnectConfig): void {
    const config = this.config();
    if (config) {
      this.config.set({ ...config, MIRTH_CONNECT: mirthConfig });
      this.markAsChanged();
    }
  }

  /**
   * Handle Submission config changes
   */
  onSubmissionConfigChange(submissionConfig: SubmissionConfig): void {
    const config = this.config();
    if (config) {
      this.config.set({ ...config, SUBMISSION: submissionConfig });
      this.markAsChanged();
    }
  }

  /**
   * Handle Processing config changes
   */
  onProcessingConfigChange(processingConfig: ProcessingConfig): void {
    const config = this.config();
    if (config) {
      this.config.set({ ...config, PROCESSING: processingConfig });
      this.markAsChanged();
    }
  }

  /**
   * Handle Submit Fields changes
   */
  onSubmitFieldsChange(submitFields: SubmitField[]): void {
    const config = this.config();
    if (config) {
      this.config.set({
        ...config,
        SUBMIT_FIELDS: submitFields,
        SUBMIT_FIELDS_CNT: submitFields.length
      });
      this.markAsChanged();
    }
  }

  /**
   * Handle Mappings changes
   */
  onMappingsChange(mappings: MhaPdsMapping[]): void {
    const config = this.config();
    if (config) {
      this.config.set({
        ...config,
        MAPPINGS: mappings,
        MAPPING_CNT: mappings.length
      });
      this.markAsChanged();
    }
  }

  /**
   * Handle MHA Locations changes
   */
  onMhaLocationsChange(locations: MhaLocation[]): void {
    const config = this.config();
    if (config) {
      this.config.set({
        ...config,
        MHA_LOCATIONS: locations,
        MHA_LOCATIONS_CNT: locations.length
      });
      this.markAsChanged();
    }
  }

  /**
   * Mark configuration as changed
   */
  private markAsChanged(): void {
    this.hasChanges.set(true);
  }

  /**
   * Show a notification message
   */
  private showNotification(type: 'success' | 'error' | 'info', message: string): void {
    this.notification.set({ type, message });
  }

  /**
   * Dismiss the current notification
   */
  dismissNotification(): void {
    this.notification.set(null);
  }

  /**
   * Get data element label by key
   */
  getDataElementLabel(key: string): string {
    return this.DATA_ELEMENT_LABELS[key as DataElementKey] || key;
  }

  /**
   * Get the current tab info
   */
  currentTabInfo = computed(() => {
    return this.tabs.find(t => t.id === this.activeTab()) || this.tabs[0];
  });
}
