import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Input,
  Output,
  signal
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MirthConnectConfig } from '../../models/mha-pds-configuration.model';

/**
 * Configuration section for Mirth Connect server settings
 *
 * Allows editing of:
 * - Server URL
 * - Username
 * - Password
 * - Timeout settings
 * - Retry attempts
 */
@Component({
  selector: 'app-config-section-mirth',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="section-content">
      <div class="form-grid">
        <!-- Server URL -->
        <div class="form-group full-width">
          <label for="mirthUrl">Server URL</label>
          <input
            type="url"
            id="mirthUrl"
            class="form-control"
            [ngModel]="config.URL"
            (ngModelChange)="onFieldChange('URL', $event)"
            placeholder="https://mirth-server.example.com:8443/api" />
          <small class="help-text">Full URL to the Mirth Connect API endpoint</small>
        </div>

        <!-- Username -->
        <div class="form-group">
          <label for="mirthUsername">Username</label>
          <input
            type="text"
            id="mirthUsername"
            class="form-control"
            [ngModel]="config.USERNAME"
            (ngModelChange)="onFieldChange('USERNAME', $event)"
            placeholder="API username" />
        </div>

        <!-- Password -->
        <div class="form-group">
          <label for="mirthPassword">Password</label>
          <div class="password-field">
            <input
              [type]="showPassword() ? 'text' : 'password'"
              id="mirthPassword"
              class="form-control"
              [ngModel]="config.PASSWORD"
              (ngModelChange)="onFieldChange('PASSWORD', $event)"
              placeholder="API password" />
            <button
              type="button"
              class="password-toggle"
              (click)="togglePasswordVisibility()">
              {{ showPassword() ? 'Hide' : 'Show' }}
            </button>
          </div>
          <small class="help-text">Leave blank to keep existing password</small>
        </div>

        <!-- Timeout -->
        <div class="form-group">
          <label for="mirthTimeout">Timeout (seconds)</label>
          <input
            type="number"
            id="mirthTimeout"
            class="form-control"
            [ngModel]="config.TIMEOUT_SECONDS"
            (ngModelChange)="onFieldChange('TIMEOUT_SECONDS', $event)"
            min="5"
            max="300"
            step="5" />
          <small class="help-text">Connection timeout (5-300 seconds)</small>
        </div>

        <!-- Retry Attempts -->
        <div class="form-group">
          <label for="mirthRetries">Retry Attempts</label>
          <input
            type="number"
            id="mirthRetries"
            class="form-control"
            [ngModel]="config.RETRY_ATTEMPTS"
            (ngModelChange)="onFieldChange('RETRY_ATTEMPTS', $event)"
            min="0"
            max="10"
            step="1" />
          <small class="help-text">Number of retries on connection failure (0-10)</small>
        </div>
      </div>

      <!-- Connection Test (UI placeholder - not functional) -->
      <div class="test-connection-section">
        <button
          type="button"
          class="btn btn-outline"
          disabled
          title="Connection testing will be available in a future release">
          Test Connection
        </button>
        <small class="help-text">Connection testing not yet implemented</small>
      </div>
    </div>
  `,
  styles: [`
    .section-content {
      max-width: 800px;
    }

    .form-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 20px;

      @media (max-width: 600px) {
        grid-template-columns: 1fr;
      }
    }

    .full-width {
      grid-column: 1 / -1;
    }

    .form-group {
      display: flex;
      flex-direction: column;
      gap: 6px;

      label {
        font-weight: 500;
        color: #333;
        font-size: 14px;
      }

      .form-control {
        padding: 10px 12px;
        border: 1px solid #ced4da;
        border-radius: 4px;
        font-size: 14px;
        transition: border-color 0.2s, box-shadow 0.2s;

        &:focus {
          outline: none;
          border-color: #0078d4;
          box-shadow: 0 0 0 3px rgba(0, 120, 212, 0.1);
        }

        &::placeholder {
          color: #adb5bd;
        }
      }

      .help-text {
        color: #6c757d;
        font-size: 12px;
      }
    }

    .password-field {
      display: flex;
      gap: 8px;

      .form-control {
        flex: 1;
      }

      .password-toggle {
        padding: 10px 16px;
        border: 1px solid #ced4da;
        background-color: #f8f9fa;
        border-radius: 4px;
        font-size: 13px;
        cursor: pointer;
        transition: background-color 0.2s;

        &:hover {
          background-color: #e9ecef;
        }
      }
    }

    .test-connection-section {
      margin-top: 24px;
      padding-top: 20px;
      border-top: 1px solid #e9ecef;
      display: flex;
      align-items: center;
      gap: 12px;

      .btn-outline {
        padding: 10px 20px;
        border: 1px solid #0078d4;
        background: transparent;
        color: #0078d4;
        border-radius: 4px;
        font-size: 14px;
        cursor: pointer;
        transition: all 0.2s;

        &:hover:not(:disabled) {
          background-color: #0078d4;
          color: white;
        }

        &:disabled {
          border-color: #ced4da;
          color: #6c757d;
          cursor: not-allowed;
        }
      }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConfigSectionMirth {
  @Input() config!: MirthConnectConfig;
  @Output() configChange = new EventEmitter<MirthConnectConfig>();

  showPassword = signal(false);

  togglePasswordVisibility(): void {
    this.showPassword.update(v => !v);
  }

  onFieldChange(field: keyof MirthConnectConfig, value: any): void {
    const updatedConfig = { ...this.config, [field]: value };
    this.configChange.emit(updatedConfig);
  }
}
